CREATE TABLE tblProperties (
  Address VARCHAR(30) NOT NULL,
  Property_Type VARCHAR(15),
  Square_Footage INTEGER,
  Bedrooms INTEGER,
  Bathrooms INTEGER,
  Garages INTEGER,
  Starting_Bid INTEGER,
  Reserve_Price INTEGER,
  Auction_Event_ID INTEGER NOT NULL,
  Seller_Prop_ID VARCHAR(13) NOT NULL,
  CONSTRAINT COMP_KEY PRIMARY KEY (Auction_Event_ID, Address, Seller_Prop_ID),
  FOREIGN KEY (Auction_Event_ID) REFERENCES tblAuctions(Auction_ID),
  FOREIGN KEY (Seller_Prop_ID) REFERENCES tblSellers(Seller_ID)
);
